	for {
		if e := recipient.ReadJSON(&frame); e != nil {
			t.Fatal(e)
		}
		if frame["request_id"] == "server" && frame["type"] == "presence.changed" {
			continue
		}
		if frame["type"] != "pong" {
			t.Fatal("stale membership leaked", frame)
		}
		break
	}
