	v := Credential{Schema: 1, Environment: "test", AppID: "wx_s07_fixture", Token: token, IssuedAt: now, ExpiresAt: now + 3600}
	v.Generation = hash(v.Environment + "\n" + v.AppID + "\n" + v.Token)
	return v
}
