CREATE TABLE IF NOT EXISTS `chat_policy_refresh` (
  `order_id` bigint(20) unsigned NOT NULL COMMENT '订单ID，不存消息内容',
  `checked_at` datetime NOT NULL COMMENT '上次检查UTC',
  `next_check_at` datetime NOT NULL COMMENT '下一次可检查UTC',
